UPDATE emp42_eval_grade
   SET emp42_grade        = #{req.grade},
       emp42_grade_weight = #{req.gradeWeight},
       emp42_grade_score  = #{req.gradeScore},
       emp42_compare_cd   = #{req.compareCode},
       emp42_reason_yn    = #{req.reasonYn}
 WHERE emp42_eval_grade_id    = #{req.evalGradeId}
   AND emp42_eval_list_std_id = #{evalListStdId}

